/// <summary>The C handle of a <see cref="Store"/>, freed once no call holds it.</summary>
internal sealed class StoreHandle : SafeHandle
{
    /// <summary>An invalid handle, for the marshaller to fill.</summary>
    public StoreHandle() : base(IntPtr.Zero, true)
    {
    }

    public override bool IsInvalid => handle == IntPtr.Zero;

    protected override bool ReleaseHandle()
    {
        Native.tg_store_free(handle);
        return true;
    }
}

/// <summary>
/// A store of installed packs in one directory: its signed catalog, its packs and their
/// journal (D-171), shared by every language and the command line (research note
/// store-api). Long work runs as a `Job` on a thread of its own; one store runs its jobs
/// one at a time, and its other calls wait for the job running.
///
/// Packs are named as catalog paths (`np.places.tgd`) or short (`np`, `np.dem`), several
/// comma-separated. Results are blobs:
/// - `catalog`: `path`, `release`, `download`, `disk`, `components`,
///   `licence`, `state` (`available`, `installed` or `update`);
/// - `status`: `path`, `release`, `bytes`, `pinned`, `asked`, `health`
///   (`good`, `length`, `head`, `footer` or `sections`), `components`;
/// - an install or update: `path`, `release`, `fetched`, `reused`, `kept`, `changed`;
/// - a refresh: `timestamp`, `files`, `bytes`; a repair: `path`, `health`, `fetched`;
///   `remove`: `path`, `release`;
/// - `find` and `locate`: one row per place and pack that
///   covers it: `id`, `name`, `lat`, `lon`, `countries`, then the pack's `pack`, `release`,
///   `download`, `disk` and `state`, null for a place no pack in the catalog covers.
/// </summary>
/// <remarks>Its methods may run on any thread at once. Dispose frees it once no call holds it;
/// a call after Dispose throws <see cref="ObjectDisposedException"/>.</remarks>
public sealed partial class Store : IDisposable
{
    internal readonly StoreHandle handle;

    internal Store(StoreHandle handle)
    {
        this.handle = handle;
    }

    /// <summary>Frees the store once no call holds it.</summary>
    public void Dispose() => handle.Dispose();

    /// <summary>
    /// Sets up a store at `root` and opens it: the metadata mirrors `repo` and asset mirrors
    /// `assets` (comma-separated URLs), and `trusted_root`, the catalog's root metadata, which
    /// becomes its trust anchor once it verifies by itself. A store set up before is set up
    /// again with these.
    ///
    /// # Errors
    ///
    /// `ErrorCode::Refused` if the root does not verify or the store cannot be written.
    ///
    /// # Blocks
    ///
    /// While a job of this store runs, and on the disk: call it off a UI thread, or use the
    /// language's asynchronous form.
    /// </summary>
    public static unsafe Store Create(string root, string repo, string assets, ReadOnlySpan<byte> trustedRoot)
    {
        Interop.Ensure();
        using var rootUtf8 = new Utf8(root, stackalloc byte[Utf8.Stack]);
        using var repoUtf8 = new Utf8(repo, stackalloc byte[Utf8.Stack]);
        using var assetsUtf8 = new Utf8(assets, stackalloc byte[Utf8.Stack]);
        StoreHandle @out;
        int status;
        try
        {
            fixed (byte* trustedRootPtr = trustedRoot)
            {
                status = Native.tg_store_create(rootUtf8.Pointer, rootUtf8.Length, repoUtf8.Pointer, repoUtf8.Length, assetsUtf8.Pointer, assetsUtf8.Length, trustedRootPtr, (nuint)trustedRoot.Length, out @out);
            }
        }
        catch (EntryPointNotFoundException)
        {
            throw TeiGeodataException.Missing("tg_store_create");
        }
        Interop.Check(status);
        return new Store(@out);
    }

    /// <summary>
    /// The awaitable form of Create: the call runs on a thread of its own, so a wait never holds a pool thread.
    /// </summary>
    public static Task<Store> CreateAsync(string root, string repo, string assets, ReadOnlySpan<byte> trustedRoot)
    {
        var copy = trustedRoot.ToArray();
        return Interop.RunBlocking(() => Create(root, repo, assets, copy));
    }

    /// <summary>
    /// Opens the store at `root`, finishing or undoing an install a crash cut short.
    ///
    /// # Errors
    ///
    /// `ErrorCode::Refused` if it is not a store or its journal cannot be read.
    ///
    /// # Blocks
    ///
    /// While a job of this store runs, and on the disk: call it off a UI thread, or use the
    /// language's asynchronous form.
    /// </summary>
    public static unsafe Store Open(string root)
    {
        Interop.Ensure();
        using var rootUtf8 = new Utf8(root, stackalloc byte[Utf8.Stack]);
        StoreHandle @out;
        int status;
        try
        {
            status = Native.tg_store_open(rootUtf8.Pointer, rootUtf8.Length, out @out);
        }
        catch (EntryPointNotFoundException)
        {
            throw TeiGeodataException.Missing("tg_store_open");
        }
        Interop.Check(status);
        return new Store(@out);
    }

    /// <summary>
    /// The awaitable form of Open: the call runs on a thread of its own, so a wait never holds a pool thread.
    /// </summary>
    public static Task<Store> OpenAsync(string root) =>
        Interop.RunBlocking(() => Open(root));

