        }
        catch (EntryPointNotFoundException)
        {
            throw TeiGeodataException.Missing("tg_job_wait_progress");
        }
        Interop.Check(status);
        return @out;
    }

    /// <summary>
    /// The awaitable form of WaitProgress: the call runs on a thread of its own, so a wait never holds a pool thread.
    /// </summary>
    public Task<ulong> WaitProgressAsync(ulong seq, uint timeoutMs) =>
        Interop.RunBlocking(() => WaitProgress(seq, timeoutMs));

    /// <summary>
    /// The progress's sequence number: it moves on with every change.
    /// </summary>
    public unsafe ulong Seq()
    {
        ulong @out = default;
        int status;
        try
        {
            status = Native.tg_job_seq(handle, &@out);
        }
        catch (EntryPointNotFoundException)
        {
            throw TeiGeodataException.Missing("tg_job_seq");
        }
        Interop.Check(status);
        return @out;
    }

    /// <summary>
    /// Bytes received so far.
    /// </summary>
    public unsafe ulong DoneBytes()
    {
        ulong @out = default;
        int status;
        try
        {
            status = Native.tg_job_done_bytes(handle, &@out);
        }
        catch (EntryPointNotFoundException)
        {
            throw TeiGeodataException.Missing("tg_job_done_bytes");
        }
        Interop.Check(status);
        return @out;
    }

    /// <summary>
    /// Bytes expected, from the catalog's sizes: never below the bytes received, and equal
    /// to them once the job ends.
    /// </summary>
    public unsafe ulong TotalBytes()
    {
        ulong @out = default;
        int status;
        try
        {
            status = Native.tg_job_total_bytes(handle, &@out);
        }
        catch (EntryPointNotFoundException)
        {
            throw TeiGeodataException.Missing("tg_job_total_bytes");
        }
        Interop.Check(status);
        return @out;
    }

    /// <summary>
    /// Whether the job has ended (done, failed or cancelled); its result is then ready.
    /// </summary>
    public unsafe bool IsEnded()
    {
        byte @out = default;
        int status;
        try
        {
            status = Native.tg_job_is_ended(handle, &@out);
        }
        catch (EntryPointNotFoundException)
        {
            throw TeiGeodataException.Missing("tg_job_is_ended");
        }
        Interop.Check(status);
        return @out != 0;
    }

    /// <summary>
    /// Asks the job to stop at its next request or chunk; it then fails with
    /// `ErrorCode::Cancelled` and leaves the store as it was.
    /// </summary>
    public unsafe void Cancel()
    {
        int status;
        try
