            status = Native.tg_job_cancel(handle);
        }
        catch (EntryPointNotFoundException)
        {
            throw TeiGeodataException.Missing("tg_job_cancel");
        }
        Interop.Check(status);
    }

    /// <summary>
    /// The job's result, waiting for it to end.
    ///
    /// # Errors
    ///
    /// The job's: `ErrorCode::Network`, `ErrorCode::Refused`, `ErrorCode::Cancelled`,
    /// or `ErrorCode::Io` and `ErrorCode::Corrupt` for an engine's packs.
    ///
    /// # Blocks
    ///
    /// Until the job moves or ends: call it off a UI thread, or use the language's
    /// asynchronous form.
    /// </summary>
    public unsafe byte[] Result()
    {
        TgBytes @out = default;
        int status;
        try
        {
            status = Native.tg_job_result(handle, &@out);
        }
        catch (EntryPointNotFoundException)
        {
            throw TeiGeodataException.Missing("tg_job_result");
        }
        Interop.Check(status);
        return Interop.TakeBytes(@out);
    }

    /// <summary>The job's result, awaited on a thread of its own; cancelling the token cancels
    /// the job (its result is then <see cref="ErrorCode.Cancelled"/>).</summary>
    public async Task<byte[]> ResultAsync(CancellationToken cancellationToken = default)
    {
        using var registration = cancellationToken.Register(static job => ((Job)job!).TryCancel(), this);
        return await Interop.RunBlocking(Result).ConfigureAwait(false);
    }

    /// <summary>The job's progress now and each time it moves, until it ends. One thread of its
    /// own waits for the moves; a reader that falls behind gets the newest, never a stale one.
    /// Ending the enumeration early stops that thread.</summary>
    public async IAsyncEnumerable<JobProgress> ProgressAsync([EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        var channel = Channel.CreateBounded<JobProgress>(new BoundedChannelOptions(1)
        {
            FullMode = BoundedChannelFullMode.DropOldest,
            SingleReader = true,
            SingleWriter = true,
        });
        using var stop = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        Task pump = Interop.RunBlocking(() => Pump(channel.Writer, stop.Token));
        try
        {
            await foreach (JobProgress progress in channel.Reader.ReadAllAsync(cancellationToken).ConfigureAwait(false))
            {
                yield return progress;
            }
        }
        finally
        {
            await stop.CancelAsync().ConfigureAwait(false);
            await pump.ConfigureAwait(false);
        }
    }

    private void Pump(ChannelWriter<JobProgress> writer, CancellationToken stop)
    {
        try
        {
            ulong seq = Seq();
            var last = new JobProgress(DoneBytes(), TotalBytes());
            writer.TryWrite(last);
            while (!stop.IsCancellationRequested && !IsEnded())
            {
                ulong next = WaitProgress(seq, 250);
                if (next != seq)
                {
                    seq = next;
                    last = new JobProgress(DoneBytes(), TotalBytes());
                    writer.TryWrite(last);
                }
            }
            if (!stop.IsCancellationRequested)
            {
                var end = new JobProgress(DoneBytes(), TotalBytes());
                if (end != last)
                {
                    writer.TryWrite(end);
                }
            }
            writer.TryComplete();
        }
        catch (Exception e)
        {
            writer.TryComplete(e);
        }
    }

    private void TryCancel()
    {
        try
        {
            Cancel();
        }
        catch (ObjectDisposedException)
        {
        }
    }
}

