/// <summary>The trampolines C calls back through: each runs the boxed function and keeps an
/// exception for the caller, since unwinding through Rust frames is undefined.</summary>
internal static unsafe class Callbacks
{
    [UnmanagedCallersOnly]
    internal static byte U32(void* ctx, uint a0)
    {
        var box = (CallbackBox)GCHandle.FromIntPtr((nint)ctx).Target!;
        try
        {
            return ((Func<uint, bool>)box.Function)(a0) ? (byte)1 : (byte)0;
        }
        catch (Exception e)
        {
            box.Error = System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e);
            return 0;
        }
    }
}
